std::string ToUtf8(const std::wstring& s)
{
    if (s.empty()) return {};
    int n = WideCharToMultiByte(CP_UTF8, 0, s.data(), static_cast<int>(s.size()),
                                nullptr, 0, nullptr, nullptr);
    if (n <= 0) return {};
    std::string out(static_cast<size_t>(n), '\0');
    WideCharToMultiByte(CP_UTF8, 0, s.data(), static_cast<int>(s.size()),
                        &out[0], n, nullptr, nullptr);
    return out;
}

std::wstring Env(const wchar_t* name)
{
    DWORD need = GetEnvironmentVariableW(name, nullptr, 0);
    if (need == 0) return {};
    std::wstring buf(need, L'\0');
    DWORD got = GetEnvironmentVariableW(name, &buf[0], need);
    if (got == 0 || got >= need) return {};
    buf.resize(got);
    return buf;
}

std::wstring FullPath(const std::wstring& p)
{
    wchar_t buf[MAX_PATH * 2];
    DWORD n = GetFullPathNameW(p.c_str(), ARRAYSIZE(buf), buf, nullptr);
    if (n == 0 || n >= ARRAYSIZE(buf)) return p;
    return std::wstring(buf, n);
}

bool EnsureDir(const std::wstring& path)
{
    if (path.empty()) return false;

    DWORD attr = GetFileAttributesW(path.c_str());
    if (attr != INVALID_FILE_ATTRIBUTES)
        return (attr & FILE_ATTRIBUTE_DIRECTORY) != 0;

    const size_t slash = path.find_last_of(L"\\/");
    if (slash == std::wstring::npos) return false;

    const std::wstring parent = path.substr(0, slash);
    const bool isDriveRoot = (parent.size() == 2 && parent[1] == L':');
    if (!isDriveRoot && parent.size() > 1 && !EnsureDir(parent))
        return false;

    if (CreateDirectoryW(path.c_str(), nullptr)) return true;
    return GetLastError() == ERROR_ALREADY_EXISTS;
}

// ---------------------------------------------------------------------------
//  Log writing
// ---------------------------------------------------------------------------

void WriteRaw(const std::string& bytes)
{
    if (g_log == INVALID_HANDLE_VALUE || bytes.empty()) return;
    std::lock_guard<std::mutex> lock(g_writeMutex);
    DWORD written = 0;
    WriteFile(g_log, bytes.data(), static_cast<DWORD>(bytes.size()), &written, nullptr);
    // Periodic durability flush; the cache manager already makes the bytes
    // visible to other readers as soon as WriteFile returns.
    if (++g_writeCount % 32 == 0) FlushFileBuffers(g_log);
}

void LogLine(const std::wstring& text)
{
    SYSTEMTIME st;
    GetLocalTime(&st);

    wchar_t stamp[64];
    swprintf_s(stamp, ARRAYSIZE(stamp),
               L"%04u-%02u-%02u %02u:%02u:%02u.%03u ",
               static_cast<unsigned>(st.wYear),  static_cast<unsigned>(st.wMonth),
               static_cast<unsigned>(st.wDay),   static_cast<unsigned>(st.wHour),
               static_cast<unsigned>(st.wMinute),static_cast<unsigned>(st.wSecond),
               static_cast<unsigned>(st.wMilliseconds));

    const std::wstring line = std::wstring(stamp) + text;

    if (g_echo) {
        std::lock_guard<std::mutex> lock(g_consoleMutex);
        wprintf(L"%ls\n", line.c_str());
        fflush(stdout);
    }

    WriteRaw(ToUtf8(line + L"\r\n"));
}

