std::wstring TranslateKey(DWORD vk, DWORD scan)
{
    if (vk >= VK_F1 && vk <= VK_F24) {
        wchar_t b[16];
        swprintf_s(b, ARRAYSIZE(b), L"[F%u]", static_cast<unsigned>(vk - VK_F1 + 1));
        return b;
    }

    if (const wchar_t* name = NamedKey(vk))
        return name;

    BYTE ks[256] = {};
    if (!GetKeyboardState(ks))
        return {};

    WCHAR buf[8] = {};
    int rc = ToUnicodeEx(vk, scan, ks, buf, ARRAYSIZE(buf), 0, g_layout);

    if (rc > 0) {
        const bool ctrlDown = (ks[VK_CONTROL] & 0x80) != 0;
        if (ctrlDown && rc == 1 && buf[0] > 0 && buf[0] < 0x20) {
            const wchar_t c = static_cast<wchar_t>(L'A' + buf[0] - 1);
            return std::wstring(L"[CTRL+") + c + L"]";
        }
        return std::wstring(buf, static_cast<size_t>(rc));
    }

    if (rc < 0)
        return L"[DEAD]";   // accent/compose key pending; layout state consumed

    const bool altDown = (ks[VK_MENU] & 0x80) != 0;
    if (altDown) {
        wchar_t b[24];
        swprintf_s(b, ARRAYSIZE(b), L"[ALT+VK%02X]", static_cast<unsigned>(vk));
        return b;
    }

    if (vk >= 'A' && vk <= 'Z') return std::wstring(1, static_cast<wchar_t>(vk));
    if (vk >= '0' && vk <= '9') return std::wstring(1, static_cast<wchar_t>(vk));

    wchar_t b[16];
    swprintf_s(b, ARRAYSIZE(b), L"[VK%02X]", static_cast<unsigned>(vk));
    return b;
}

// ---------------------------------------------------------------------------
//  Foreground-window context
